CREATE TABLE schema_version (version INTEGER PRIMARY KEY CHECK(version=1));
INSERT INTO schema_version VALUES (1);
CREATE TABLE businesses (tenant_id TEXT PRIMARY KEY, name TEXT NOT NULL, idea TEXT NOT NULL, founded TEXT NOT NULL, end_date TEXT NOT NULL, synthetic INTEGER NOT NULL CHECK(synthetic=1), config_json TEXT NOT NULL);
CREATE TABLE departments (tenant_id TEXT NOT NULL, id TEXT NOT NULL, name TEXT NOT NULL, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id) REFERENCES businesses(tenant_id));
CREATE TABLE agents (tenant_id TEXT NOT NULL, id TEXT NOT NULL, department_id TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL, salary_cents INTEGER NOT NULL CHECK(salary_cents>=0), permissions_json TEXT NOT NULL, fictional INTEGER NOT NULL CHECK(fictional=1), PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,department_id) REFERENCES departments(tenant_id,id));
CREATE TABLE projects (tenant_id TEXT NOT NULL, id TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('planned','active','complete')), PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id) REFERENCES businesses(tenant_id));
CREATE TABLE tasks (tenant_id TEXT NOT NULL, id TEXT NOT NULL, project_id TEXT NOT NULL, agent_id TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','complete')), PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id), FOREIGN KEY(tenant_id,agent_id) REFERENCES agents(tenant_id,id));
CREATE TABLE stakeholders (tenant_id TEXT NOT NULL, id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('customer','supplier','partner','investor')), name TEXT NOT NULL, fictional INTEGER NOT NULL CHECK(fictional=1), PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id) REFERENCES businesses(tenant_id));
CREATE TABLE business_events (tenant_id TEXT NOT NULL, id TEXT NOT NULL, seq INTEGER NOT NULL CHECK(seq>0), occurred TEXT NOT NULL, kind TEXT NOT NULL, actor_id TEXT NOT NULL, source_ref TEXT NOT NULL, payload_json TEXT NOT NULL, prev_hash TEXT NOT NULL, event_hash TEXT NOT NULL, PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,seq), FOREIGN KEY(tenant_id,actor_id) REFERENCES agents(tenant_id,id));
CREATE TABLE transactions (tenant_id TEXT NOT NULL, id TEXT NOT NULL, event_id TEXT NOT NULL, stakeholder_id TEXT, kind TEXT NOT NULL CHECK(kind IN ('sale','refund','expense','payroll','capital')), amount_cents INTEGER NOT NULL CHECK(amount_cents>0), PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,event_id), FOREIGN KEY(tenant_id,event_id) REFERENCES business_events(tenant_id,id), FOREIGN KEY(tenant_id,stakeholder_id) REFERENCES stakeholders(tenant_id,id));
CREATE TABLE transaction_lines (tenant_id TEXT NOT NULL, transaction_id TEXT NOT NULL, line_no INTEGER NOT NULL, item_id TEXT NOT NULL, qty INTEGER NOT NULL CHECK(qty>0), unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>0), PRIMARY KEY(tenant_id,transaction_id,line_no), FOREIGN KEY(tenant_id,transaction_id) REFERENCES transactions(tenant_id,id));
CREATE TABLE financial_records (tenant_id TEXT NOT NULL, transaction_id TEXT NOT NULL, line_no INTEGER NOT NULL, account TEXT NOT NULL CHECK(account IN ('cash','revenue','operating_expense','payroll_expense','capital')), debit_cents INTEGER NOT NULL CHECK(debit_cents>=0), credit_cents INTEGER NOT NULL CHECK(credit_cents>=0), CHECK((debit_cents>0 AND credit_cents=0) OR (credit_cents>0 AND debit_cents=0)), PRIMARY KEY(tenant_id,transaction_id,line_no), FOREIGN KEY(tenant_id,transaction_id) REFERENCES transactions(tenant_id,id));
CREATE TABLE engineering_evidence (tenant_id TEXT NOT NULL, id TEXT NOT NULL, path TEXT NOT NULL, sha256 TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('inspected','executed')), limitation TEXT NOT NULL, PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id) REFERENCES businesses(tenant_id));
CREATE VIEW finance_summary AS SELECT tenant_id,
 SUM(CASE WHEN account='revenue' THEN credit_cents-debit_cents ELSE 0 END) AS net_revenue_cents,
 SUM(CASE WHEN account IN ('operating_expense','payroll_expense') THEN debit_cents-credit_cents ELSE 0 END) AS expense_cents,
 SUM(CASE WHEN account='cash' THEN debit_cents-credit_cents ELSE 0 END) AS cash_cents,
 SUM(CASE WHEN account='capital' THEN credit_cents-debit_cents ELSE 0 END) AS capital_cents
 FROM financial_records GROUP BY tenant_id;
